mapper.select:
select t.id as id, t.account_id as accountId, t.account_name as accountName, t.batch_no as batchNo, t.transaction_type as transactionType, t.amount as amount, t.balance as balance, t.transaction_time as transactionTime, t.remark as remark from finance_account_transaction t where t.del_flag = '0'
and t.account_id = #{req.accountId}
and t.transaction_time >= #{req.transactionTimeStart}
and t.transaction_time <= #{req.transactionTimeEnd}
and t.transaction_type = #{req.transactionType}
order by t.transaction_time desc, t.id desc

select ifnull(sum(t.amount), 0)
from finance_account_transaction t
where t.del_flag = '0'

    and t.account_id = #{req.accountId}


    and t.transaction_time >= #{req.transactionTimeStart}


    and t.transaction_time <= #{req.transactionTimeEnd}


    and t.transaction_type = #{req.transactionType}
